//! App-private immutable files, resumable staging and disposable FIFO cache.
use crate::Result;
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::BTreeMap,fs::{self,File,OpenOptions},io::{Read,Seek,SeekFrom,Write},path::{Path,PathBuf}};
const MIB:u64=1024*1024;
const CHUNK:usize=65536;
#[derive(Clone,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct Limits{pub documents:u64,pub files:u64,pub cache:u64}
impl Default for Limits{fn default()->Self{Self{documents:16*MIB,files:64*MIB,cache:32*MIB}}}
#[derive(Clone,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
struct Entry{name:String,mime:String,cache:bool,ready:bool,sha256:String,order:u64}
#[derive(Default,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
struct Index{serial:u64,entries:BTreeMap<String,Entry>}
fn valid_id(id:&str)->bool{crate::valid_id(id)}
fn directory(root:&Path)->Result<PathBuf>{let p=root.join("private-blobs-v1");fs::create_dir_all(&p).map_err(|e|e.to_string())?;if !fs::symlink_metadata(&p).map_err(|e|e.to_string())?.is_dir(){return Err("Invalid private file directory".into())}Ok(p)}
fn path(root:&Path,id:&str)->Result<PathBuf>{if !valid_id(id){return Err("Invalid private file handle".into())}Ok(directory(root)?.join(format!("{id}.data")))}
fn size(root:&Path,id:&str)->Result<u64>{let m=fs::symlink_metadata(path(root,id)?).map_err(|e|e.to_string())?;if !m.is_file()||m.len()>1024*MIB{return Err("Invalid private file".into())}Ok(m.len())}
fn metadata_valid(e:&Entry)->bool{!e.name.is_empty()&&e.name.encode_utf16().count()<=128&&!e.name.chars().any(|c|c.is_control()||c=='/'||c=='\\')&&e.mime.len()<=100&&e.mime.split_once('/').is_some_and(|(a,b)|!a.is_empty()&&!b.is_empty()&&!b.contains('/'))&&e.mime.bytes().all(|c|c.is_ascii_alphanumeric()||b"/!#$&^_.+-".contains(&c))&&e.order>0&&(!e.ready||e.sha256.len()==64&&e.sha256.bytes().all(|c|c.is_ascii_hexdigit()&&!c.is_ascii_uppercase()))}
fn index(root:&Path)->Result<Index>{let p=root.join("private-blobs-v1.json");let i=match fs::symlink_metadata(&p){Err(e)if e.kind()==std::io::ErrorKind::NotFound=>Index::default(),Err(e)=>return Err(e.to_string()),Ok(_)=>serde_json::from_slice(&crate::sdk::read_bounded(&p,1024*1024)?).map_err(|e|format!("Private file index could not be read: {e}"))?};if i.entries.len()>1024||i.entries.iter().any(|(id,e)|!valid_id(id)||!metadata_valid(e)||e.order>i.serial){return Err("Private file index is damaged; files were not changed".into())}for id in i.entries.keys(){size(root,id)?;}Ok(i)}
pub(crate) fn limits(root:&Path)->Result<Limits>{let p=root.join("storage-limits.json");let v=match fs::symlink_metadata(&p){Err(e)if e.kind()==std::io::ErrorKind::NotFound=>{let mut policy=Limits::default();if root.file_name().and_then(|n|n.to_str())==Some("app.onklav.ebooks"){policy.files=1024*MIB;}policy},Err(e)=>return Err(e.to_string()),Ok(_)=>serde_json::from_slice(&crate::sdk::read_bounded(&p,1024)?).map_err(|e|e.to_string())?};if !(16*MIB..=128*MIB).contains(&v.documents)||!(16*MIB..=1024*MIB).contains(&v.files)||v.cache>256*MIB{return Err("Invalid private storage limits".into())}Ok(v)}
fn save(root:&Path,i:&Index)->Result<()>{let p=root.join("private-blobs-v1.json");let bytes=serde_json::to_vec(i).map_err(|e|e.to_string())?;if bytes.len()>1024*1024||crate::sdk::private_size(root,&p)?+bytes.len()as u64>limits(root)?.documents{return Err("Private metadata quota reached".into())}crate::sdk::atomic(&p,&bytes)}
fn usage(root:&Path,i:&Index,cache:bool)->Result<u64>{let mut total=0u64;for(id,e)in &i.entries{if e.cache==cache{total=total.checked_add(size(root,id)?).ok_or("Private file quota overflow")?;}}Ok(total)}
fn discard(root:&Path,old:&Index,new:&Index){for id in old.entries.keys().filter(|id|!new.entries.contains_key(*id)){let _=fs::remove_file(path(root,id).unwrap());}}
fn collect_orphans(root:&Path,i:&Index)->Result<()>{for entry in fs::read_dir(directory(root)?).map_err(|e|e.to_string())?.take(2048){let entry=entry.map_err(|e|e.to_string())?;let name=entry.file_name();let Some(id)=name.to_str().and_then(|s|s.strip_suffix(".data"))else{continue};if valid_id(id)&&!i.entries.contains_key(id)&&entry.file_type().map_err(|e|e.to_string())?.is_file(){fs::remove_file(entry.path()).map_err(|e|e.to_string())?;}}Ok(())}
fn room(root:&Path,i:&mut Index,cache:bool,extra:u64,keep:Option<&str>,limit:u64)->Result<()>{let used=usage(root,i,cache)?;if used.checked_add(extra).is_some_and(|n|n<=limit){return Ok(())}if !cache{return Err("Saved-file quota reached. Remove files or ask the user to raise the limit in Settings".into())}let mut candidates=i.entries.iter().filter(|(id,e)|e.cache&&e.ready&&Some(id.as_str())!=keep).map(|(id,e)|(e.order,id.clone())).collect::<Vec<_>>();candidates.sort();let mut remaining=used;let mut remove=Vec::new();for(_,id)in candidates{if remaining.checked_add(extra).is_some_and(|n|n<=limit){break}remaining=remaining.saturating_sub(size(root,&id)?);remove.push(id);}if remaining.checked_add(extra).is_none_or(|n|n>limit){return Err("Cache quota reached; finish or cancel active cache imports".into())}for id in remove{i.entries.remove(&id);}Ok(())}
fn info(root:&Path,i:&Index,id:&str)->Result<Value>{let e=i.entries.get(id).ok_or("Private file is unavailable or was evicted")?;Ok(json!({"id":id,"name":e.name,"mime":e.mime,"cache":e.cache,"ready":e.ready,"size":size(root,id)?,"sha256":if e.ready{Some(&e.sha256)}else{None}}))}
fn hex(bytes:&[u8])->String{const DIGITS:&[u8]=b"0123456789abcdef";let mut out=String::with_capacity(bytes.len()*2);for b in bytes{out.push(DIGITS[(b>>4)as usize]as char);out.push(DIGITS[(b&15)as usize]as char);}out}
fn decode(value:&str)->Result<Vec<u8>>{if value.is_empty()||value.len()>CHUNK*2||value.len()%2!=0||!value.bytes().all(|b|b.is_ascii_hexdigit()){return Err("Use a nonempty file chunk up to64KiB".into())}value.as_bytes().chunks_exact(2).map(|b|u8::from_str_radix(std::str::from_utf8(b).unwrap(),16).map_err(|e|e.to_string())).collect()}
pub(crate) fn service(root:&Path,service:&str,args:&Value)->Result<Value>{service_with_id(root,service,args,None)}
/// Stable host-only staging identity bridges a process interruption between the
/// Rust file commit and Android job-record commit. Guests cannot choose blob IDs.
pub(crate) fn begin_job(root:&Path,args:&Value,token:&str)->Result<Value>{
 if token.len()!=36||uuid::Uuid::parse_str(token).is_err(){return Err("Invalid host job token".into())}
 let id=hex(&Sha256::digest(format!("onklav.job.stage.v1\0{token}").as_bytes()))[..32].to_owned();
 service_with_id(root,"blobs.begin",args,Some(id))
}
fn service_with_id(root:&Path,service:&str,args:&Value,fixed:Option<String>)->Result<Value>{
 let allowed:&[&str]=match service{"blobs.begin"=>&["name","mime","cache"],"blobs.info"|"blobs.delete"=>&["id"],"blobs.append"=>&["id","offset","hex"],"blobs.finish"=>&["id","sha256"],"blobs.read"=>&["id","offset","length"],"blobs.list"=>&["after","limit"],"blobs.usage"|"blobs.clear_cache"=>&[],_=>return Err("Unsupported private file service".into())};
 let object=args.as_object().ok_or("Private file arguments must be an object")?;if object.keys().any(|k|!allowed.contains(&k.as_str()))||args.to_string().len()>CHUNK*2+2048{return Err("Unsupported or oversized private file arguments".into())}
 let mut i=index(root)?;let policy=limits(root)?;
 match service{
 "blobs.usage"=>Ok(json!({"documents_used":crate::sdk::private_size(root,&root.join("unused"))?,"files_used":usage(root,&i,false)?,"cache_used":usage(root,&i,true)?,"limits":policy,"count":i.entries.len(),"chunk_bytes":CHUNK})),
 "blobs.begin"=>{if let Some(id)=fixed.as_ref(){if let Some(entry)=i.entries.get(id){if args["name"].as_str()!=Some(&entry.name)||args["mime"].as_str().unwrap_or("application/octet-stream")!=entry.mime||args["cache"].as_bool().unwrap_or(false)!=entry.cache{return Err("Host staging metadata changed".into())}return info(root,&i,id)}}if i.entries.len()>=1024{return Err("Private file handle limit reached".into())}let entry=Entry{name:args["name"].as_str().ok_or("Choose a file name")?.into(),mime:args["mime"].as_str().unwrap_or("application/octet-stream").into(),cache:match args.get("cache"){None=>false,Some(v)=>v.as_bool().ok_or("Cache must be true or false")?},ready:false,sha256:String::new(),order:i.serial.checked_add(1).ok_or("Private file sequence exhausted")?};if !metadata_valid(&entry){return Err("Choose a bounded display name and MIME type".into())}if entry.cache&&policy.cache==0{return Err("Cache storage is disabled in Settings".into())}collect_orphans(root,&i)?;let id=fixed.unwrap_or_else(||uuid::Uuid::new_v4().simple().to_string());OpenOptions::new().write(true).create_new(true).open(path(root,&id)?).map_err(|e|e.to_string())?;i.serial=entry.order;i.entries.insert(id.clone(),entry);if let Err(e)=save(root,&i){let _=fs::remove_file(path(root,&id)?);return Err(e)}info(root,&i,&id)},
 "blobs.list"=>{let after=match args.get("after"){None=>"",Some(v)=>v.as_str().filter(|v|v.is_empty()||valid_id(v)).ok_or("Invalid file cursor")?};let limit=match args.get("limit"){None=>40,Some(v)=>v.as_u64().filter(|n|(1..=40).contains(n)).ok_or("Page size must be1–40")? as usize};let ids=i.entries.keys().filter(|id|id.as_str()>after).take(limit+1).collect::<Vec<_>>();let rows=ids.iter().take(limit).map(|id|info(root,&i,id)).collect::<Result<Vec<_>>>()?;Ok(json!({"items":rows,"next":if ids.len()>limit{rows.last().and_then(|r|r["id"].as_str())}else{None}}))},
 "blobs.clear_cache"=>{let old=index(root)?;i.entries.retain(|_,e|!e.cache);save(root,&i)?;discard(root,&old,&i);collect_orphans(root,&i)?;Ok(json!({"cleared":true}))},
 _=>{let id=args["id"].as_str().filter(|id|valid_id(id)).ok_or("Choose a private file handle")?;let entry=i.entries.get(id).cloned().ok_or("Private file is unavailable or was evicted")?;
 match service{
 "blobs.info"=>info(root,&i,id),
 "blobs.delete"=>{let old=index(root)?;i.entries.remove(id);save(root,&i)?;discard(root,&old,&i);collect_orphans(root,&i)?;Ok(json!({"deleted":true}))},
 "blobs.append"=>{if entry.ready{return Err("Committed files are immutable; create a new file".into())}let bytes=decode(args["hex"].as_str().ok_or("Choose a file chunk")?)?;let offset=args["offset"].as_u64().ok_or("Choose a file offset")?;let current=size(root,id)?;
  if offset!=current{if offset.checked_add(bytes.len()as u64)==Some(current){let mut f=File::open(path(root,id)?).map_err(|e|e.to_string())?;f.seek(SeekFrom::Start(offset)).map_err(|e|e.to_string())?;let mut previous=vec![0;bytes.len()];f.read_exact(&mut previous).map_err(|e|e.to_string())?;if previous==bytes{return Ok(json!({"size":current,"repeated":true}))}}return Err("File offset changed; inspect the current size before resuming".into())}
  if current.checked_add(bytes.len()as u64).is_none_or(|n|n>1024*MIB){return Err("Private file exceeds1GiB".into())}let old=index(root)?;room(root,&mut i,entry.cache,bytes.len()as u64,Some(id),if entry.cache{policy.cache}else{policy.files})?;if i.entries.len()!=old.entries.len(){save(root,&i)?;discard(root,&old,&i);}
  OpenOptions::new().append(true).open(path(root,id)?).and_then(|mut f|f.write_all(&bytes)).map_err(|e|e.to_string())?;Ok(json!({"size":current+bytes.len()as u64,"repeated":false}))},
 "blobs.finish"=>{if entry.ready{if args.get("sha256").is_some_and(|v|v.as_str()!=Some(&entry.sha256)){return Err("File checksum did not match".into())}return info(root,&i,id)}let mut f=File::open(path(root,id)?).map_err(|e|e.to_string())?;let mut digest=Sha256::new();let mut buffer=[0u8;CHUNK];loop{let n=f.read(&mut buffer).map_err(|e|e.to_string())?;if n==0{break}digest.update(&buffer[..n]);}let digest=hex(&digest.finalize());if let Some(expected)=args.get("sha256"){if expected.as_str()!=Some(&digest){return Err("File checksum did not match; staging was retained".into())}}f.sync_all().map_err(|e|e.to_string())?;let row=i.entries.get_mut(id).unwrap();row.ready=true;row.sha256=digest;save(root,&i)?;info(root,&i,id)},
 "blobs.read"=>{if !entry.ready{return Err("Finish the file before reading".into())}let offset=args["offset"].as_u64().ok_or("Choose a file offset")?;let length=match args.get("length"){None=>CHUNK,Some(v)=>v.as_u64().filter(|n|(1..=CHUNK as u64).contains(n)).ok_or("Read1–65536 bytes at a time")? as usize};let total=size(root,id)?;if offset>total{return Err("File offset is beyond the end".into())}let mut f=File::open(path(root,id)?).map_err(|e|e.to_string())?;f.seek(SeekFrom::Start(offset)).map_err(|e|e.to_string())?;let mut bytes=vec![0;length.min((total-offset)as usize)];f.read_exact(&mut bytes).map_err(|e|e.to_string())?;Ok(json!({"hex":hex(&bytes),"offset":offset,"next":offset+bytes.len()as u64,"eof":offset+bytes.len()as u64==total}))},_=>Err("Unsupported private file service".into())}}
 }
}
pub(crate) fn resolve(root:&Path,id:&str)->Result<Value>{let i=index(root)?;if !i.entries.get(id).is_some_and(|e|e.ready){return Err("Private file is unavailable or unfinished".into())}let mut value=info(root,&i,id)?;value["path"]=json!(path(root,id)?.to_str().ok_or("Invalid private file path")?);Ok(value)}
pub(crate) fn read_all(root:&Path,id:&str,max:u64)->Result<Vec<u8>>{let value=resolve(root,id)?;if value["size"].as_u64().unwrap_or(u64::MAX)>max{return Err("Backup file is too large".into())}crate::sdk::read_bounded(&path(root,id)?,max)}
pub(crate) fn save_bytes(root:&Path,name:&str,mime:&str,bytes:&[u8])->Result<Value>{let created=service(root,"blobs.begin",&json!({"name":name,"mime":mime}))?;let id=created["id"].as_str().unwrap();let result=(||{for(offset,part)in bytes.chunks(CHUNK).enumerate(){service(root,"blobs.append",&json!({"id":id,"offset":offset*CHUNK,"hex":hex(part)}))?;}service(root,"blobs.finish",&json!({"id":id}))})();if result.is_err(){let _=service(root,"blobs.delete",&json!({"id":id}));}result}
pub(crate) fn admin(root:&Path,args:&Value)->Result<Value>{let operation=args["operation"].as_str().unwrap_or("info");match operation{
 "info"=>service(root,"blobs.usage",&json!({})),"clear_cache"=>service(root,"blobs.clear_cache",&json!({})),
 "limits"=>{let object=args.as_object().ok_or("Choose storage limits")?;if object.keys().any(|k|!["operation","documents","files","cache"].contains(&k.as_str())){return Err("Unsupported storage limit".into())}let policy=Limits{documents:args["documents"].as_u64().ok_or("Choose a document limit")?,files:args["files"].as_u64().ok_or("Choose a file limit")?,cache:args["cache"].as_u64().ok_or("Choose a cache limit")?};if !(16*MIB..=128*MIB).contains(&policy.documents)||!(16*MIB..=1024*MIB).contains(&policy.files)||policy.cache>256*MIB{return Err("Storage limits are outside supported bounds".into())}let mut i=index(root)?;if usage(root,&i,false)?>policy.files{return Err("Saved files exceed that limit. No saved files were deleted".into())}let p=root.join("storage-limits.json");let bytes=serde_json::to_vec(&policy).map_err(|e|e.to_string())?;if crate::sdk::private_size(root,&p)?+bytes.len()as u64>policy.documents{return Err("Documents exceed that limit. No documents were deleted".into())}let old=index(root)?;room(root,&mut i,true,0,None,policy.cache)?;if i.entries.len()!=old.entries.len(){save(root,&i)?;discard(root,&old,&i);}crate::sdk::atomic(&p,&bytes)?;service(root,"blobs.usage",&json!({}))},_=>Err("Unsupported storage management operation".into())}}
pub(crate) fn native_args(service:&str,args:&Value)->Result<()>{let allowed=if service=="blobs.import"{vec!["cache"]}else{vec!["id"]};let o=args.as_object().ok_or("Invalid file action arguments")?;if o.keys().any(|k|!allowed.contains(&k.as_str())){return Err("Unsupported file action argument".into())}if service=="blobs.import"{if args.get("cache").is_some_and(|v|!v.is_boolean()){return Err("Cache must be true or false".into())}}else if args["id"].as_str().is_none_or(|id|!valid_id(id)){return Err("Choose a private file handle".into())}Ok(())}

#[cfg(test)]mod tests{
 use super::*;
 fn begin(root:&Path,cache:bool)->String{service(root,"blobs.begin",&json!({"name":"Book.m4b","mime":"audio/mp4","cache":cache})).unwrap()["id"].as_str().unwrap().into()}
 fn write(root:&Path,id:&str,offset:u64,bytes:&[u8])->Result<Value>{service(root,"blobs.append",&json!({"id":id,"offset":offset,"hex":hex(bytes)}))}
 fn finish(root:&Path,id:&str)->Value{service(root,"blobs.finish",&json!({"id":id})).unwrap()}
 #[test]fn storage_staging_retry_checksum_and_immutable_commit(){let d=tempfile::tempdir().unwrap();let r=d.path();let id=begin(r,false);assert!(service(r,"blobs.read",&json!({"id":id,"offset":0})).is_err());write(r,&id,0,b"hello").unwrap();assert_eq!(write(r,&id,0,b"hello").unwrap()["repeated"],true);assert!(write(r,&id,0,b"wrong").is_err());assert!(service(r,"blobs.finish",&json!({"id":id,"sha256":"wrong"})).is_err());assert_eq!(service(r,"blobs.info",&json!({"id":id})).unwrap()["ready"],false);let ready=finish(r,&id);assert_eq!(ready["size"],5);assert!(write(r,&id,5,b"!").is_err());let read=service(r,"blobs.read",&json!({"id":id,"offset":1,"length":2})).unwrap();assert_eq!(read["hex"],"656c");assert_eq!(read["next"],3);assert_eq!(read["eof"],false);assert!(service(r,"blobs.finish",&json!({"id":id,"sha256":"wrong"})).is_err());}
 #[test]fn storage_streams_a_file_larger_than_the_guest_memory_budget(){let d=tempfile::tempdir().unwrap();let r=d.path();let id=begin(r,false);let bytes=vec![37u8;CHUNK];for n in 0..160{write(r,&id,n*CHUNK as u64,&bytes).unwrap();}let ready=finish(r,&id);assert_eq!(ready["size"],10*MIB);let tail=service(r,"blobs.read",&json!({"id":id,"offset":10*MIB-3,"length":64})).unwrap();assert_eq!(tail["hex"],"252525");assert_eq!(tail["eof"],true);}
 #[test]fn storage_cache_eviction_and_lower_limits_preserve_saved_files(){let d=tempfile::tempdir().unwrap();let r=d.path();admin(r,&json!({"operation":"limits","documents":16*MIB,"files":16*MIB,"cache":MIB})).unwrap();let saved=begin(r,false);write(r,&saved,0,b"saved").unwrap();finish(r,&saved);let old=begin(r,true);OpenOptions::new().write(true).open(path(r,&old).unwrap()).unwrap().set_len(MIB).unwrap();finish(r,&old);let new=begin(r,true);write(r,&new,0,b"new").unwrap();finish(r,&new);assert!(service(r,"blobs.info",&json!({"id":old})).is_err());assert!(service(r,"blobs.info",&json!({"id":saved})).is_ok());admin(r,&json!({"operation":"limits","documents":16*MIB,"files":16*MIB,"cache":0})).unwrap();assert!(service(r,"blobs.info",&json!({"id":new})).is_err());assert_eq!(service(r,"blobs.info",&json!({"id":saved})).unwrap()["size"],5);assert!(service(r,"blobs.begin",&json!({"name":"cache","cache":true})).is_err());}
 #[test]fn storage_lower_saved_quota_and_unknown_admin_effect_never_delete_data(){let d=tempfile::tempdir().unwrap();let r=d.path();let id=begin(r,false);OpenOptions::new().write(true).open(path(r,&id).unwrap()).unwrap().set_len(17*MIB).unwrap();assert!(admin(r,&json!({"operation":"limits","documents":16*MIB,"files":16*MIB,"cache":0})).is_err());assert_eq!(size(r,&id).unwrap(),17*MIB);assert_eq!(limits(r).unwrap().files,64*MIB);assert!(service(r,"blobs.limits",&json!({"files":1024*MIB})).is_err());}
 #[test]fn storage_foreign_handles_corruption_and_symlinks_are_rejected(){let d=tempfile::tempdir().unwrap();let a=d.path().join("a");let b=d.path().join("b");fs::create_dir(&a).unwrap();fs::create_dir(&b).unwrap();let id=begin(&a,false);write(&a,&id,0,b"private").unwrap();finish(&a,&id);assert!(service(&b,"blobs.info",&json!({"id":id})).is_err());assert!(service(&a,"blobs.info",&json!({"id":"../other"})).is_err());let original=fs::read(path(&a,&id).unwrap()).unwrap();fs::write(a.join("private-blobs-v1.json"),b"damaged").unwrap();assert!(service(&a,"blobs.clear_cache",&json!({})).is_err());assert_eq!(original,fs::read(path(&a,&id).unwrap()).unwrap());}
 #[cfg(unix)]#[test]fn storage_symlinked_directory_never_touches_external_files(){use std::os::unix::fs::symlink;let d=tempfile::tempdir().unwrap();let a=d.path().join("a");let b=d.path().join("b");fs::create_dir(&a).unwrap();fs::create_dir(&b).unwrap();fs::write(b.join("keep"),b"keep").unwrap();symlink(&b,a.join("private-blobs-v1")).unwrap();assert!(service(&a,"blobs.begin",&json!({"name":"file"})).is_err());assert_eq!(fs::read(b.join("keep")).unwrap(),b"keep");}
 #[test]fn storage_reopen_resumes_staging_without_replaying_appends(){let d=tempfile::tempdir().unwrap();let r=d.path();let id=begin(r,false);write(r,&id,0,b"first").unwrap();assert_eq!(service(r,"blobs.info",&json!({"id":id})).unwrap()["size"],5);write(r,&id,5,b"second").unwrap();finish(r,&id);assert_eq!(service(r,"blobs.read",&json!({"id":id,"offset":0})).unwrap()["hex"],hex(b"firstsecond"));service(r,"blobs.delete",&json!({"id":id})).unwrap();assert!(!path(r,&id).unwrap().exists());}
}

#[cfg(test)]mod job_recovery_tests{use super::*;
 #[test]fn storage_job_staging_is_idempotent_across_missing_host_receipts(){let d=tempfile::tempdir().unwrap();let r=d.path();let args=json!({"name":"Download.mp3","mime":"audio/mpeg"});let token=uuid::Uuid::new_v4().to_string();let a=begin_job(r,&args,&token).unwrap();let id=a["id"].as_str().unwrap();let again=begin_job(r,&args,&token).unwrap();assert_eq!(again["id"],a["id"]);service(r,"blobs.append",&json!({"id":id,"offset":0,"hex":"30313233"})).unwrap();assert_eq!(begin_job(r,&args,&token).unwrap()["size"],4);let finished=service(r,"blobs.finish",&json!({"id":id})).unwrap();assert_eq!(begin_job(r,&args,&token).unwrap()["sha256"],finished["sha256"]);assert_eq!(service(r,"blobs.usage",&json!({})).unwrap()["count"],1);assert!(begin_job(r,&json!({"name":"Changed.mp3","mime":"audio/mpeg"}),&token).is_err());}
 #[test]fn storage_job_staging_recovers_an_untracked_empty_file_without_touching_other_files(){let d=tempfile::tempdir().unwrap();let r=d.path();let args=json!({"name":"Download.mp3","mime":"audio/mpeg"});let token=uuid::Uuid::new_v4().to_string();let a=begin_job(r,&args,&token).unwrap();let id=a["id"].as_str().unwrap();service(r,"blobs.delete",&json!({"id":id})).unwrap();File::create(path(r,id).unwrap()).unwrap();let other=save_bytes(r,"Saved.mp3","audio/mpeg",b"saved").unwrap();assert_eq!(begin_job(r,&args,&token).unwrap()["id"],a["id"]);assert_eq!(read_all(r,other["id"].as_str().unwrap(),100).unwrap(),b"saved");assert_ne!(begin_job(r,&args,&uuid::Uuid::new_v4().to_string()).unwrap()["id"],a["id"]);}
}
